      borderBottomWidth: 1,
      borderBottomColor: '#eee',
      paddingBottom: 10,
  },
  modalTitle: {
      fontSize: 18,
      fontWeight: 'bold',
      color: '#333',
  },
  closeBtn: {
      padding: 5,
  },
  modalItem: {
      paddingVertical: 12,
      borderBottomWidth: 1,
      borderBottomColor: '#f9f9f9',
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
  },
  modalItemText: {
      fontSize: 16,
      color: '#333',
  },
  emptyState: {
      padding: 20,
      alignItems: 'center',
  },
  emptyText: {
      marginTop: 10,
      color: '#666',
  }
});

export default SignupScreen;
